#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000

/** 基于链表实现队列 **/
typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));
    link->size = 0;
    link->head = NULL;
    link->tail = NULL;
    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));
    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

int removeFirst_LinkedList(LinkedList *link) {
    if (link->size == 0) exit(-1);

    ListNode *removed = link->head;

    if (link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    return removed->ele;
}

int cmp(const void *a, const void *b) {
    return *((int *) a) - *((int *) b);
}

int main() {
    int n;
    scanf("%d", &n);

    // 记录每个点的入度
    int inDegree[MAX_SIZE] = {0};
    // 记录每个点的后继点集合
    LinkedList *next[MAX_SIZE] = {NULL};

    // 记录图中点
    LinkedList *points = new_LinkedList();
    int occurs[MAX_SIZE] = {0};

    for (int i = 0; i < n; i++) {
        // 从 a 到 b 的路径
        int a, b;
        scanf("%d %d", &a, &b);

        // 收集图中所有节点
        if (!occurs[a]) {
            addLast_LinkedList(points, a);
            occurs[a] = 1;
        }

        if (!occurs[b]) {
            addLast_LinkedList(points, b);
            occurs[b] = 1;
        }

        // b点入度+1
        inDegree[b] += 1;

        if (next[a] == NULL) {
            next[a] = new_LinkedList();
        }
        // a点的后继点集合纳入b
        addLast_LinkedList(next[a], b);
    }

    // 图中总共total个节点
    int total = points->size;
    // head记录图的头节点
    int head = 0;

    // 队列记录入度为0的点
    LinkedList *queue = new_LinkedList();

    ListNode *cur = points->head;
    while (cur != NULL) {
        int p = cur->ele;

        // 题目描述中说图中只有一个首节点，首节点是入度为0的节点，因此如果某节点p没有入度，则为头节点
        if (inDegree[p] == 0) {
            head = p;
            addLast_LinkedList(queue, p);
            break;
        }

        cur = cur->next;
    }

    // tails记录所有尾节点
    int tails[MAX_SIZE];
    int tails_size = 0;

    // count记录已被剥去的点个数，如果图中存在环，则必然最终count < total
    int count = 0;

    while (queue->size > 0) {
        // 剥离入度为0的点
        int fa = removeFirst_LinkedList(queue);
        count++;

        // 如果fa没有后继点，即fa没有出度，则fa是尾节点
        if (next[fa] == NULL) {
            tails[tails_size++] = fa;
            continue;
        }

        // 如果fa有后继点，则其所有后继点入度-1
        ListNode *cur = next[fa]->head;
        while (cur != NULL) {
            int ch = cur->ele;

            inDegree[ch] -= 1;

            // 如果ch点入度变为0，则加入队列
            if (inDegree[ch] == 0) {
                addLast_LinkedList(queue, ch);
            }

            cur = cur->next;
        }
    }


    if (count != total) {
        // 如果存在环，则必然count < total
        printf("-1");
    } else {
        // 如果不存在环，则打印头节点和尾节点
        printf("%d ", head);

        // 注意本题描述存在冲突（用例2输出的尾节点是从小到大排序的，而题目输出描述是要求尾节点从大到小排序），这里以用例为准
        qsort(tails, tails_size, sizeof(int), cmp);

        for (int i = 0; i < tails_size; i++) {
            printf("%d", tails[i]);

            if (i < tails_size - 1) {
                printf(" ");
            }
        }
    }


    return 0;
}
